def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    import subprocess
    import os
    from concurrent.futures import ThreadPoolExecutor, as_completed
    from typing import Sequence, Any

    if target_concurrency < 1:
        raise ValueError("target_concurrency must be at least 1")

    def execute_with_args(args: list[str]) -> tuple[int, bytes]:
        try:
            if color and os.name == 'posix':
                result = subprocess.run(['script', '-q', '/dev/null', '--'] + list(cmd) + args, capture_output=True)
            else:
                result = subprocess.run(cmd + tuple(args), capture_output=True)
            return result.returncode, result.stdout
        except Exception as e:
            print(f"Error executing command: {e}")
            return -1, bytes()

    # Split varargs into chunks for each concurrently running process
    chunk_size = max(1, len(varargs) // target_concurrency)
    arg_chunks = [varargs[i:i + chunk_size] for i in range(0, len(varargs), chunk_size)]

    results = []
    with ThreadPoolExecutor(max_workers=target_concurrency) as executor:
        future_to_args = {executor.submit(execute_with_args, args): args for args in arg_chunks}
        for future in as_completed(future_to_args):
            try:
                return_code, output = future.result()
                results.append((return_code, output))
            except Exception as e:
                print(f"Error retrieving result: {e}")
                results.append((-1, bytes()))

    # Assuming we want to return the first non-zero exit code and its output, or (0, b'') if all succeed
    for return_code, output in results:
        if return_code != 0:
            return return_code, output

    return 0, b''

