        print(f"An error occurred while normalizing the command: {e}")
        return cmd

def cached(cache, key=hashkey, lock=None):
    def decorator(func):
        def wrapper(*args, **kwargs):
            k = key(*args, **kwargs)
            try:
                with lock:
                    if k in cache:
                        return cache[k]
            except TypeError:
                pass  # lock is None or not a context manager
            except Exception as e:
                raise RuntimeError("Error while acquiring lock") from e

            result = func(*args, **kwargs)
            try:
                with lock:
                    cache[k] = result
            except TypeError:
                pass  # lock is None or not a context manager
            except Exception as e:
                raise RuntimeError("Error while releasing lock or updating cache") from e
            return result
        return wrapper
    return decorator

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.
    """
    from functools import lru_cache as functools_lru_cache

    if not isinstance(maxsize, int) or maxsize < 0:
        raise ValueError("maxsize must be a non-negative integer")
    if not isinstance(typed, bool):
        raise TypeError("typed must be a boolean")

    def decorator(func):
        return functools_lru_cache(maxsize=maxsize, typed=typed)(func)

    return decorator

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    if not hasattr(self, '_order'):
        raise AttributeError("This method requires the object to have an _order attribute.")
    if not self._order:
        raise KeyError("popitem(): dictionary is empty")
    key = self._order.pop(0)
    value = self.pop(key)
    return key, value

