def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            k = key(*args, **kwargs)
            if lock:
                with lock:
                    if k in cache:
                        return cache[k]
                    result = func(*args, **kwargs)
                    cache[k] = result
                    return result
            else:
                if k in cache:
                    return cache[k]
                result = func(*args, **kwargs)
                cache[k] = result
                return result
        return wrapper
    return decorator

def extostr(cls, e, max_level=30, max_path_level=5):
    try:
        if not isinstance(e, Exception):
            raise ValueError("The provided object is not an instance of Exception.")

        if not isinstance(max_level, int) or max_level <= 0:
            raise ValueError("max_level must be a positive integer.")

        if not isinstance(max_path_level, int) or max_path_level <= 0:
            raise ValueError("max_path_level must be a positive integer.")

        exc_type = type(e).__name__
        exc_message = str(e)
        trace = []
        import traceback
        for frame_info in traceback.extract_tb(e.__traceback__):
            filename = '/'.join(frame_info.filename.split('/')[-max_path_level:])
            trace.append(f"File '{filename}', line {frame_info.lineno}, in {frame_info.name}\n  {frame_info.line or ''}")
            if len(trace) >= max_level:
                break

        trace_str = "\n".join(trace)
        return f"{exc_type}: {exc_message}\n{''.join(trace)}"
    except Exception as err:
        return f"Error formatting exception: {str(err)}"

