def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.
    """
    try:
        if not orderings:
            return []

        # Create a dictionary to map each element to the next element in its ordering
        next_element = {}
        for ordering in orderings:
            for i in range(len(ordering) - 1):
                next_element[ordering[i]] = ordering[i + 1]

        # Find all starting elements (those not preceded by any other element)
        start_elements = set(orderings[0])
        for ordering in orderings[1:]:
            start_elements.update(ordering)
        for ordering in orderings:
            for element in ordering[1:]:
                start_elements.discard(element)

        # Perform a topological sort starting from the start elements
        merged_ordering = []
        visited = set()

        def visit(node):
            if node in visited:
                return
            visited.add(node)
            if node in next_element:
                visit(next_element[node])
            merged_ordering.insert(0, node)

        for start in start_elements:
            visit(start)

        return merged_ordering

    except Exception as e:
        raise ValueError(f"An error occurred while merging orderings: {e}")

