def _validate_labels(labels):
    import re
    from collections.abc import Iterable

    class ValidationError(Exception):
        def __init__(self, messages):
            super().__init__(self)
            self.messages = messages

    key_regex = re.compile(r'^[a-zA-Z0-9_\-]+$')
    value_regex = re.compile(r'^[a-zA-Z0-9_\-]+(\.[a-zA-Z0-9_\-]+)*$')
    errors = []

    for key, value in labels.items():
        key_str = str(key) if not isinstance(key, str) else key
        value_str = str(value) if not isinstance(value, str) else value

        if isinstance(key, (list, dict, set, Iterable)) or not isinstance(key, str):
            errors.append({key_str: 'expected string or bytes-like object'})
        elif not key_regex.match(key):
            errors.append({key_str: f"Label key '{key_str}' does not match the regex '^[a-zA-Z0-9_\-]+$'"})

        if isinstance(value, (list, dict, set, Iterable)) and not isinstance(value, str):
            errors.append({value_str: 'expected string or bytes-like object'})
        elif isinstance(value, str) and not value_regex.match(value):
            errors.append({value_str: f"Label value '{value_str}' does not match the regex '^[a-zA-Z0-9_\-]+(\\.[a-zA-Z0-9_\-]+)*$'"})

    if errors:
        raise ValidationError(errors)

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    if not isinstance(manifest_dict, dict):
        raise ValueError("manifest_dict must be a dictionary")

    observer_schema = {}
    identifying_fields = {'apiVersion', 'kind', 'metadata'}

    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            observer_schema[key] = generate_default_observer_schema_dict(value, False)
        elif isinstance(value, list):
            observer_schema[key] = [generate_default_observer_schema_dict(item, False) if isinstance(item, dict) else None for item in value]
        else:
            if first_level and key in identifying_fields:
                observer_schema[key] = value
            else:
                observer_schema[key] = None

    return observer_schema

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    for field, schema in observer_schema.items():
        try:
            if field not in last_applied_manifest:
                last_applied_manifest[field] = response[field]
            if isinstance(schema, dict) and isinstance(response[field], dict):
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[field], schema, response[field]
                )
        except KeyError:
            raise KeyError(f"The observed field '{field}' is not present in the Kubernetes response")

def generate_default_observer_schema(app):
    try:
        if not hasattr(app, 'spec') or not hasattr(app.spec, 'manifest'):
            raise ValueError("Application is missing 'spec.manifest' attribute")

        if not isinstance(app.spec.manifest, dict):
            raise ValueError("'spec.manifest' should be a dictionary")

        default_schema = {}
        for resource_type, resource in app.spec.manifest.items():
            if resource_type not in app.observer_schema:
                default_schema[resource_type] = {
                    "type": "object",
                    "properties": {
                        "status": {"type": "object"}
                    }
                }
        return default_schema

    except Exception as e:
        raise RuntimeError(f"Failed to generate default observer schema: {e}")

def format(
        self,
        sql: AnyStr,
        params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    try:
        if isinstance(params, dict):
            # Assuming named parameter style
            out_style_params = {f"${key}": value for key, value in params.items()}
            formatted_sql = sql
            for key in out_style_params:
                formatted_sql = formatted_sql.replace(f":{key[1:]}", key)
            return formatted_sql, out_style_params
        elif isinstance(params, Sequence):
            # Assuming ordinal parameter style
            out_style_params = [f"${i + 1}" for i in range(len(params))]
            formatted_sql = sql
            for i, param in enumerate(out_style_params):
                formatted_sql = formatted_sql.replace(f"%s", param, 1)
            return formatted_sql, out_style_params
        else:
            raise ValueError("params must be a dict or a sequence")
    except Exception as e:
        raise RuntimeError(f"Error formatting SQL query: {e}")

def formatmany(
        self,
        sql: AnyStr,
        many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    try:
        # Assuming self.SQLParams.in_style is defined and can be either 'named' or 'ordinal'
        in_style = getattr(self, 'SQLParams', NamedTuple('SQLParams', [('in_style', str)]))('named').in_style
        out_style = 'qmark'  # Example out-style, could be 'numeric', 'named', 'format', 'pyformat'

        # Mapping from in-style to out-style placeholders
        style_map = {
            'named': (':', '?'),
            'ordinal': ('%s', '?')
        }

        if in_style not in style_map:
            raise ValueError(f"Unsupported in-style: {in_style}")

        in_placeholder, out_placeholder = style_map[in_style]

        out_params = []
        formatted_sql = sql

        for params in many_params:
            if in_style == 'named':
                if not isinstance(params, dict):
                    raise TypeError("For named parameters, params must be a dict")
                out_params.append(list(params.values()))
                for key in params:
                    formatted_sql = formatted_sql.replace(f"{in_placeholder}{key}", out_placeholder)
            elif in_style == 'ordinal':
                if not isinstance(params, (list, tuple)):
                    raise TypeError("For ordinal parameters, params must be a list or tuple")
                out_params.append(list(params))
                formatted_sql = formatted_sql.replace(in_placeholder, out_placeholder, len(params))

        return formatted_sql, out_params

    except Exception as e:
        # Handle any exceptions that occur during processing
        print(f"An error occurred: {e}")
        return sql, []

