def _extract_number_and_supplment_from_issue_element(issue):
    if not isinstance(issue, str):
        raise ValueError("Input must be a string")

    issue = issue.strip()
    number = None
    suppl = None

    # Check for number at the start
    if issue.isdigit():
        number = issue
        issue = issue[len(number):].strip()
    else:
        import re
        match = re.match(r'(\d+-\d+|\d+)', issue)
        if match:
            number = match.group(0)
            issue = issue[len(number):].strip()

    # Check for supplment keywords
    suppl_keywords = ['suppl', 'supp', 'spe', 'sp', 's', 'pr', '.']
    issue_lower = issue.lower()

    for keyword in suppl_keywords:
        if keyword in issue_lower:
            suppl = issue_lower
            break

    if suppl is None and issue_lower:
        suppl = issue_lower

    return number, suppl

def pretty(self, indent=0, debug=False):
    try:
        indent_str = '  ' * indent
        if hasattr(self, '__dict__'):
            items = self.__dict__.items()
        elif hasattr(self, '__iter__') and not isinstance(self, str):
            items = enumerate(self)
        else:
            return indent_str + repr(self)

        result = [indent_str + type(self).__name__ + ' {']
        for key, value in items:
            if debug:
                key_str = f'{key!r}: '
            else:
                key_str = f'{key}: ' if isinstance(key, str) else f'{key}: '
            if hasattr(value, 'pretty'):
                result.append(key_str + value.pretty(indent + 1, debug))
            elif isinstance(value, (list, tuple, dict)):
                if isinstance(value, dict):
                    value_items = value.items()
                else:
                    value_items = enumerate(value)
                result.append(indent_str + '  ' + key_str + '[')
                for v_key, v_value in value_items:
                    v_key_str = f'{v_key!r}: ' if isinstance(v_key, str) else f'{v_key}: '
                    if hasattr(v_value, 'pretty'):
                        result.append(indent_str + '    ' + v_key_str + v_value.pretty(indent + 2, debug))
                    else:
                        result.append(indent_str + '    ' + v_key_str + repr(v_value))
                result.append(indent_str + '  ]')
            else:
                result.append(indent_str + '  ' + key_str + repr(value))
        result.append(indent_str + '}')
        return '\n'.join(result)
    except Exception as e:
        return f"{indent_str}Error: {str(e)}"

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    if not isinstance(args, list):
        raise ValueError("args must be a list of expressions")

    def apply_absorption(expr):
        if len(expr) != 3:
            return expr
        op, left, right = expr
        if op == '&':
            if right == ('|', left, '__B__'):
                return left
            if right == ('&', ('~', left), '__B__'):
                return ('&', left, right[2])
        elif op == '|':
            if right == ('&', left, '__B__'):
                return left
            if right == ('|', ('~', left), '__B__'):
                return ('|', left, right[2])
        return expr

    result = []
    for expr in args:
        simplified_expr = apply_absorption(expr)
        result.append(simplified_expr)
    return result

