def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import os

    if not isinstance(commands, list) or not commands:
        raise ValueError("Commands must be a non-empty list.")
    if not isinstance(args, list):
        raise ValueError("Arguments must be a list.")
    if cwd is not None and not os.path.isdir(cwd):
        raise ValueError("cwd must be a valid directory path.")
    if env is not None and not isinstance(env, dict):
        raise ValueError("env must be a dictionary.")

    command = [commands[0]] + commands[1:] + args
    try:
        subproc_env = os.environ.copy() if env is None else env.update(os.environ) or env
        result = subprocess.run(
            command,
            cwd=cwd,
            capture_output=not verbose and hide_stderr,
            text=True,
            env=subproc_env,
            stderr=subprocess.PIPE if hide_stderr else subprocess.STDOUT
        )
        if verbose:
            print(result.stdout)
            if result.stderr:
                print(result.stderr, file=sys.stderr)
        if result.returncode != 0:
            raise subprocess.CalledProcessError(result.returncode, command, output=result.stdout, stderr=result.stderr)
        return result.stdout
    except subprocess.CalledProcessError as e:
        if not verbose:
            print(f"Command '{' '.join(e.cmd)}' failed with return code {e.returncode}.", file=sys.stderr)
            if e.stderr:
                print(e.stderr, file=sys.stderr)
        raise
    except FileNotFoundError:
        raise FileNotFoundError(f"Command '{commands[0]}' not found.")
    except Exception as e:
        raise RuntimeError(f"An error occurred: {e}")

def register_vcs_handler(vcs, method):
    def decorator(func):
        def wrapper(*args, **kwargs):
            if args[0].vcs == vcs:
                return method(func, *args, **kwargs)
            else:
                raise ValueError(f"VCS type {vcs} does not match the expected type {args[0].vcs}.")
        return wrapper
    return decorator

