def validate_version_inventories(self, version_dirs):
    if not isinstance(version_dirs, list):
        raise ValueError("version_dirs must be a list of version directory names.")

    if any(not isinstance(version, str) for version in version_dirs):
        raise ValueError("All elements in version_dirs must be strings.")

    root_inventory = {}
    try:
        with open('root_inventory.json', 'r') as file:
            root_inventory = json.load(file)
    except FileNotFoundError:
        raise FileNotFoundError("Root inventory file 'root_inventory.json' not found.")
    except json.JSONDecodeError:
        raise ValueError("Root inventory file 'root_inventory.json' is not a valid JSON file.")

    differing_digests = {}

    for version in version_dirs:
        version_inventory_path = f"{version}/inventory.json"
        try:
            with open(version_inventory_path, 'r') as file:
                version_inventory = json.load(file)
        except FileNotFoundError:
            print(f"Warning: Inventory file '{version_inventory_path}' not found. Skipping this version.")
            continue
        except json.JSONDecodeError:
            print(f"Warning: Inventory file '{version_inventory_path}' is not a valid JSON file. Skipping this version.")
            continue

        for item, digest in version_inventory.items():
            if item not in root_inventory or root_inventory[item] != digest:
                if item not in differing_digests:
                    differing_digests[item] = set()
                differing_digests[item].add(digest)

    return differing_digests

def find_path_type(path):
    try:
        if not isinstance(path, str) or not path:
            return "invalid input: path must be a non-empty string"

        import os

        if not os.path.exists(path):
            return f"path does not exist: {path}"

        if os.path.isfile(path):
            return 'file'

        namaste_file = os.path.join(path, '0=ocfl_1.0')
        if os.path.isfile(namaste_file):
            with open(namaste_file, 'r') as f:
                content = f.read().strip()
                if content == 'ocfl_1.0':
                    if os.path.isfile(os.path.join(path, 'inventory.json')):
                        return 'object'
                    else:
                        return 'root'
        return 'unknown OCFL type'
    except Exception as e:
        return f"error determining path type: {str(e)}"

