def deep_merge_nodes(nodes):
    from ruamel.yaml.nodes import MappingNode, ScalarNode

    def merge_values(key, value1, value2):
        if isinstance(value1, MappingNode) and isinstance(value2, MappingNode):
            # Merge two MappingNodes
            merged_value = value1.value[:]
            value1_keys = {item[0].value: index for index, item in enumerate(merged_value)}
            for item in value2.value:
                sub_key = item[0]
                if sub_key.value in value1_keys:
                    # If key exists, deep merge the values
                    merged_value[value1_keys[sub_key.value]] = (sub_key, merge_values(sub_key, merged_value[value1_keys[sub_key.value]][1], item[1]))
                else:
                    # If key does not exist, add the new key-value pair
                    merged_value.append(item)
            return MappingNode(tag=value1.tag, value=merged_value)
        else:
            # Non-MappingNode values: last one wins
            return value2

    merged_dict = {}
    for key_node, value_node in nodes:
        key = key_node.value
        if key in merged_dict:
            merged_dict[key] = merge_values(key_node, merged_dict[key][1], value_node)
        else:
            merged_dict[key] = (key_node, value_node)

    return [item for item in merged_dict.values()]

