            merged_dict[key] = (key_node, value_node)
        else:
            _, existing_value_node = merged_dict[key]
            if isinstance(value_node, MappingNode) and isinstance(existing_value_node, MappingNode):
                existing_value_dict = dict(existing_value_node.value)
                value_dict = dict(value_node.value)
                for sub_key_node, sub_value_node in value_node.value:
                    key = sub_key_node.value
                    existing_value_dict[key] = (sub_key_node, sub_value_node)
                existing_value_node.value = list(existing_value_dict.values())
            else:
                merged_dict[key] = (key_node, value_node)

    return list(merged_dict.values())

def parser_flags(parser):
    try:
        flags = []
        for action in parser._actions:
            if action.option_strings:
                flags.extend(action.option_strings)
        return ' '.join(flags)
    except Exception as e:
        return str(e)

def parse_arguments(*unparsed_arguments):
    import argparse

    parser = argparse.ArgumentParser()
    subparsers = parser.add_subparsers(dest='subparser_name')

    # Example subparser setup
    parser_global = subparsers.add_parser('global')
    parser_global.add_argument('--global-option', type=str, help='A global option')

    parser_sub1 = subparsers.add_parser('sub1')
    parser_sub1.add_argument('--sub1-option', type=int, help='An option for subparser 1')

    parser_sub2 = subparsers.add_parser('sub2')
    parser_sub2.add_argument('--sub2-option', type=float, help='An option for subparser 2')

    try:
        args = parser.parse_args(unparsed_arguments)
        result = {args.subparser_name: args}
        if args.subparser_name is None:
            result = {"global": args}
        return result
    except argparse.ArgumentError as e:
        print(f"Argument error: {e}")
        return {}
    except SystemExit as e:
        print(f"System exit: {e}")
        return {}

def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_results = {}
    remaining_arguments = list(unparsed_arguments)

    for subparser_name, parser in subparsers.items():
        try:
            # Attempt to parse all arguments with the current subparser
            parsed_namespace, remaining = parser.parse_known_args(unparsed_arguments)
            parsed_results[subparser_name] = parsed_namespace
            # Update remaining arguments only if this subparser found something
            if set(remaining) != set(unparsed_arguments):
                remaining_arguments = remaining
        except Exception as e:
            # If parsing fails, log the error and skip to the next subparser
            print(f"Failed to parse arguments with subparser {subparser_name}: {e}")

    return parsed_results, remaining_arguments

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.upper()
    try:
        if size.endswith('G'):
            return int(float(size[:-1]) * 1_000_000_000)
        elif size.endswith('M'):
            return int(float(size[:-1]) * 1_000_000)
        elif size.endswith('K'):
            return int(float(size[:-1]) * 1_000)
        else:
            return int(size)
    except ValueError:
        raise ValueError("Invalid size format. Use a number followed by 'K', 'M', or 'G' if needed.")

def _dictsum(dicts):
    result = {}
    for d in dicts:
        if not isinstance(d, dict):
            raise ValueError("All elements in the iterable must be dictionaries.")
        for key, value in d.items():
            if not isinstance(value, (int, float)):
                raise ValueError("All dictionary values must be numbers.")
            if key in result:
                result[key] += value
            else:
                result[key] = value
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not isinstance(url, str):
        raise ValueError("The url parameter must be a string.")
    if not isinstance(url_args, dict):
        raise ValueError("The url_args parameter must be a dictionary.")

    try:
        for key, value in url_args.items():
            placeholder = f"{{{key}}}"
            if placeholder in url:
                url = url.replace(placeholder, str(value))
    except Exception as e:
        raise RuntimeError(f"An error occurred while replacing URL arguments: {e}")

    return url

