def regex_dict(item):
    def convert_to_regex(pattern):
        # Escape all characters except for the wildcard '*'
        regex = re.escape(pattern)
        # Replace the escaped wildcard with the regex equivalent
        regex = regex.replace(r'\*', '.*')
        # Add start and end anchors
        return f'^{regex}$'

    if not isinstance(item, dict):
        raise ValueError("Input must be a dictionary")

    regex_keys = {}
    for key, value in item.items():
        if not isinstance(key, str):
            raise ValueError("All keys must be strings")
        try:
            regex_key = convert_to_regex(key)
            regex_keys[regex_key] = value
        except Exception as e:
            raise ValueError(f"Error converting key '{key}' to regex: {e}")

    return regex_keys

def unquote(name):
