def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None

    parts = frequency.split()
    if len(parts) != 2:
        raise ValueError("Frequency must be in the format 'number unit'")

    try:
        number = int(parts[0])
    except ValueError:
        raise ValueError("The number part of the frequency must be an integer")

    unit = parts[1].lower()
    if unit == "weeks":
        return datetime.timedelta(weeks=number)
    elif unit == "days":
        return datetime.timedelta(days=number)
    elif unit == "hours":
        return datetime.timedelta(hours=number)
    elif unit == "minutes":
        return datetime.timedelta(minutes=number)
    elif unit == "seconds":
        return datetime.timedelta(seconds=number)
    else:
        raise ValueError(f"Unknown unit of time: {unit}")

def make_find_paths(find_paths):
    def is_pattern(s):
        return ':' in s or '*' in s or '?' in s or '[' in s or ']' in s

    transformed_paths = []
    for path in find_paths:
        if not is_pattern(path):
            # Transform the path into a glob pattern
            path = 'sh:**/*' + path + '*/**'
        transformed_paths.append(path)
    return transformed_paths

