def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    if roots is None:
        roots = set()
    try:
        # Find all nodes that have no parent
        all_children = set()
        all_parents = set()
        for _, child, _ in graph.triples((None, prop, None)):
            all_children.add(child)
        for _, _, parent in graph.triples((None, prop, None)):
            all_parents.add(parent)
        root_candidates = all_parents - all_children
        roots.update(root_candidates)
        # Recursively find roots among the root candidates
        for candidate in root_candidates:
            find_roots(graph, prop, roots)
    except Exception as e:
        print(f"An error occurred: {e}")
    return roots

