def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    try:
        mu = 0.2
        sigma = 0.1
        return np.exp(-0.5 * ((x - mu) / sigma) ** 2) / (sigma * np.sqrt(2 * np.pi))
    except Exception as e:
        return f"An error occurred: {str(e)}"

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import logging
    import os
    import json

    if overrides is None:
        overrides = {}

    config_data = {}
    log_records = []

    for filename in config_filenames:
        try:
            with open(filename, 'r') as file:
                config = json.load(file)
                if resolve_env:
                    config = {k: os.path.expandvars(v) if isinstance(v, str) else v for k, v in config.items()}
                config_data[filename] = {**config, **overrides}
        except FileNotFoundError:
            log_records.append(logging.LogRecord(name='config_loader', level=logging.ERROR,
                                                pathname='', lineno=0, msg=f"File not found: {filename}",
                                                args=(), exc_info=True))
        except json.JSONDecodeError as e:
            log_records.append(logging.LogRecord(name='config_loader', level=logging.ERROR,
                                                pathname='', lineno=0, msg=f"Error decoding JSON from {filename}: {e}",
                                                args=(), exc_info=True))
        except Exception as e:
            log_records.append(logging.LogRecord(name='config_loader', level=logging.ERROR,
                                                pathname='', lineno=0, msg=f"Unexpected error processing {filename}: {e}",
                                                args=(), exc_info=True))

    return config_data, log_records

def from_ticks(cls, ticks, tz=None):
    if not isinstance(ticks, int):
        raise ValueError("ticks must be an integer")
    if ticks < 0 or ticks >= 86400000000000:
        raise ValueError("ticks is out of bounds (0 <= ticks < 86400000000000)")
    seconds = ticks // 1_000_000_000
    nanoseconds = ticks % 1_000_000_000
    minutes, seconds = divmod(seconds, 60)
    hours, minutes = divmod(minutes, 60)
    return cls(hour=hours, minute=minutes, second=seconds, microsecond=nanoseconds // 1000, tzinfo=tz)

