def fromutc(self, dt):
    try:
        if dt.tzinfo is None:
            raise ValueError("The provided datetime object must be timezone-aware.")

        # Convert the datetime to UTC
        utc_dt = dt.astimezone(datetime.timezone.utc)

        # Localize the UTC datetime to the desired timezone
        localized_dt = self.localize(utc_dt.replace(tzinfo=None))

        # Check if the datetime is in a fold
        fold = (localized_dt.utcoffset() != localized_dt.replace(fold=not localized_dt.fold).utcoffset())

        return localized_dt.replace(fold=fold)
    except Exception as e:
        raise ValueError(f"An error occurred while converting the datetime: {e}")

