def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    import re
    from typing import Set, Tuple

    tags = set()
    code_block = False
    lines = text.split('\n')
    result_lines = []

    for line in lines:
        if line.strip().startswith(''):
            code_block = not code_block
            result_lines.append(line)
            continue

        if code_block:
            result_lines.append(line)
            continue

        tag_pattern = r'(?<!\w)(#\w+)(?!\w)'
        found_tags = re.findall(tag_pattern, line)

        for tag in found_tags:
            tags.add(tag)
            if replacer:
                line = re.sub(tag_pattern, replacer(tag), line)

        result_lines.append(line)

    return tags, '\n'.join(result_lines)

