def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    import requests
    import xml.etree.ElementTree as ET

    if not isinstance(handle, str) or not handle:
        raise ValueError("Invalid handle provided")

    try:
        response = requests.get(f"https://{handle}/.well-known/webfinger?resource=acct:{handle}")
        response.raise_for_status()
    except requests.RequestException as e:
        raise RuntimeError(f"Failed to retrieve webfinger document: {e}")

    try:
        root = ET.fromstring(response.content)
    except ET.ParseError as e:
        raise RuntimeError(f"Failed to parse webfinger document: {e}")

    parsed_data = {
        'subject': root.find('{http://openid.net/xmlns/2009/01/webfinger}subject').text
    }

    links = root.findall('{http://openid.net/xmlns/2009/01/webfinger}link')
    parsed_data['links'] = [
        {
            'rel': link.get('rel'),
            'href': link.get('href'),
            'type': link.get('type')
        }
        for link in links
    ]

    return parsed_data

