        include_directive = parser_dict.pop('include')
        if not isinstance(include_directive, dict):
            raise ValueError("include directive must be a dictionary")

        for key, value in include_directive.items():
            if key in parser_dict:
                raise KeyError(f"Duplicate key found: {key}")
