def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    try:
        from infrared import api
        import subprocess

        if not playbook_path:
            raise ValueError("playbook_path is required")

        command = ['ansible-playbook', playbook_path]

        if verbose:
            command.extend(['-v'] * verbose)

        if extra_vars:
            command.append('--extra-vars')
            command.append(api.to_json(extra_vars))

        if ansible_args:
            for key, value in ansible_args.items():
                if value is None:
                    command.append(f'--{key}')
                else:
                    command.extend([f'--{key}', str(value)])

        subprocess.run(command, check=True)

    except Exception as e:
        raise RuntimeError(f"An error occurred while running ansible-playbook: {e}")

def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    try:
        # Convert the vars_dict to a format suitable for Ansible extra-vars
        extra_vars = ' '.join([f'{key}={value}' for key, value in vars_dict.items()])

        # Construct the full command to run Ansible
        command = ['ansible-playbook'] + cli_args + ['-e', extra_vars]

        # Execute the command
        import subprocess
        result = subprocess.run(command, check=True, cwd=ir_workspace.path, capture_output=True, text=True)

        # Return the Ansible results
        return {'returncode': result.returncode, 'stdout': result.stdout, 'stderr': result.stderr}

    except subprocess.CalledProcessError as e:
        return {'returncode': e.returncode, 'stdout': e.stdout, 'stderr': e.stderr}
    except Exception as e:
        return {'returncode': 1, 'stdout': '', 'stderr': str(e)}

