def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    def flatten_dict(d, parent_key='', sep='_'):
        items = []
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(flatten_dict(v, new_key, sep=sep).items())
            else:
                items.append((new_key, v))
        return dict(items)

    plugin_spec_path = os.path.join(plugin_dir, 'plugin_spec.json')
    try:
        with open(plugin_spec_path, 'r') as file:
            plugin_spec = json.load(file)
            return flatten_dict(plugin_spec)
    except FileNotFoundError:
        raise Exception(f"Plugin spec file not found at {plugin_spec_path}")
    except json.JSONDecodeError:
        raise Exception(f"Error decoding JSON from plugin spec file at {plugin_spec_path}")
    except Exception as e:
        raise Exception(f"An error occurred while processing the plugin spec file: {str(e)}")

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    import os
    try:
        if os.getenv('CONFIG_PATH') is None:
            # Assuming a default config path, modify as necessary
            default_config_path = '/path/to/default/config'
            os.environ['CONFIG_PATH'] = default_config_path
    except Exception as e:
        print(f"An error occurred while setting the CONFIG_PATH environment variable: {e}")

def extend_cli(self, root_subparsers):
    try:
        if not root_subparsers:
            raise ValueError("The root_subparsers object cannot be None or empty.")

        # Assuming we are adding a new subparser for 'spec' command
        spec_parser = root_subparsers.add_parser('spec', help='Command to handle spec operations.')

        # Example of adding arguments to the spec command
        spec_parser.add_argument('--input', required=True, help='Path to the input specification file.')
        spec_parser.add_argument('--output', default='output.txt', help='Path to the output file.')

        # Additional arguments can be added as needed
    except Exception as e:
        print(f"An error occurred while extending CLI: {e}")

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not path.startswith(root):
        raise ValueError("Path does not start with the specified root.")
    return path[len(root):].lstrip('/')
